-- Minimal Supabase-compatible fixture for the UGC calculators and badge migration.
do $roles$
begin
    if not exists (select 1 from pg_roles where rolname='anon') then create role anon nologin; end if;
    if not exists (select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin; end if;
    if not exists (select 1 from pg_roles where rolname='service_role') then create role service_role nologin; end if;
end
$roles$;

create schema auth;
create table auth.users (
    id uuid primary key,
    email text not null unique,
    email_confirmed_at timestamptz
);
create or replace function auth.uid()
returns uuid
language sql
stable
as $function$
    select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid;
$function$;

create or replace function auth.jwt()
returns jsonb
language sql
stable
as $function$
    select jsonb_build_object(
        'sub',auth.uid()::text,
        'email',(select email from auth.users where id=auth.uid())
    );
$function$;
grant usage on schema auth to authenticated, anon, service_role;
grant execute on function auth.uid() to public;

create schema private;
create table private.worth_it_calc_wallets (
    user_id uuid primary key references auth.users(id) on delete cascade,
    balance_milli integer not null default 0 check (balance_milli >= 0),
    premium_plan text not null default 'free',
    premium_expires_at timestamptz,
    updated_at timestamptz not null default now()
);
alter table private.worth_it_calc_wallets enable row level security;
revoke all on private.worth_it_calc_wallets from public,anon,authenticated;

create table public.worth_it_profiles (
    user_id uuid primary key references auth.users(id) on delete cascade,
    worth_it_id bigint not null unique,
    username text,
    display_name text not null,
    avatar_url text,
    created_at timestamptz not null default now()
);
alter table public.worth_it_profiles enable row level security;
revoke all on public.worth_it_profiles from public,anon,authenticated;

create table public.worth_it_user_preferences (
    user_id uuid primary key references auth.users(id) on delete cascade,
    profile_visibility text not null default 'public'
);
create table public.worth_it_friends (
    user_low_id uuid not null references auth.users(id) on delete cascade,
    user_high_id uuid not null references auth.users(id) on delete cascade,
    primary key(user_low_id,user_high_id)
);

create table public.worth_it_follows (
    follower_user_id uuid not null references auth.users(id) on delete cascade,
    followed_user_id uuid not null references auth.users(id) on delete cascade,
    created_at timestamptz not null default now(),
    primary key(follower_user_id,followed_user_id),
    check(follower_user_id<>followed_user_id)
);

create table public.worth_it_social_notifications (
    id bigint generated by default as identity primary key,
    recipient_user_id uuid not null references auth.users(id) on delete cascade,
    actor_user_id uuid not null references auth.users(id) on delete cascade,
    notification_type text not null check(notification_type in ('unfriended')),
    reason text,
    created_at timestamptz not null default now(),
    read_at timestamptz,
    constraint worth_it_social_notifications_not_self check(recipient_user_id<>actor_user_id),
    constraint worth_it_social_notifications_reason_length check(reason is null or char_length(reason)<=500)
);

create table public.worth_it_notification_dismissals (
    user_id uuid not null references auth.users(id) on delete cascade,
    notification_kind text not null,
    notification_id text not null,
    dismissed_at timestamptz not null default now(),
    primary key(user_id,notification_kind,notification_id)
);


-- Minimal CALC transaction fixture so the UGC policy migration can tie a successful
-- calculator use to the existing reserve/settle flow.
create table private.worth_it_calc_transactions (
    id bigint generated by default as identity primary key,
    user_id uuid not null references auth.users(id) on delete cascade,
    kind text not null,
    currency text not null default 'CALC',
    amount_milli integer not null default 0,
    balance_after_milli integer not null default 0,
    status text not null default 'reserved',
    request_id uuid,
    description text not null default '',
    metadata jsonb not null default '{}'::jsonb,
    created_at timestamptz not null default now(),
    hidden_at timestamptz,
    unique (user_id, request_id)
);
alter table private.worth_it_calc_transactions enable row level security;
revoke all on private.worth_it_calc_transactions from public, anon, authenticated;

create or replace function public.calc_wallet_settle(p_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, private, auth
as $function$
declare
    v_user_id uuid := auth.uid();
    v_tx private.worth_it_calc_transactions%rowtype;
begin
    if v_user_id is null then raise exception 'Authentication required' using errcode = '28000'; end if;
    update private.worth_it_calc_transactions
       set status = 'completed'
     where user_id = v_user_id and request_id = p_request_id and status = 'reserved'
    returning * into v_tx;
    if not found then
        select * into v_tx from private.worth_it_calc_transactions
         where user_id = v_user_id and request_id = p_request_id;
        if not found then return jsonb_build_object('ok', false, 'code', 'RESERVATION_NOT_FOUND'); end if;
        return jsonb_build_object('ok', v_tx.status = 'completed', 'status', v_tx.status);
    end if;
    return jsonb_build_object('ok', true, 'status', 'completed', 'balance_milli', v_tx.balance_after_milli);
end;
$function$;
revoke all on function public.calc_wallet_settle(uuid) from public, anon;
grant execute on function public.calc_wallet_settle(uuid) to authenticated;

create or replace function public.calc_wallet_summary()
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, private, auth
as $function$
begin
    if auth.uid() is null then raise exception 'Authentication required.' using errcode='28000'; end if;
    insert into private.worth_it_calc_wallets(user_id)
    values(auth.uid()) on conflict(user_id) do nothing;
    return jsonb_build_object('ok',true,'fixture',true);
end;
$function$;

create or replace function public.calc_wallet_refund(p_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, private, auth
as $function$
declare
    v_tx private.worth_it_calc_transactions%rowtype;
    v_wallet private.worth_it_calc_wallets%rowtype;
    v_refund integer;
begin
    if auth.uid() is null then raise exception 'Authentication required.' using errcode='28000'; end if;
    select * into v_wallet from private.worth_it_calc_wallets
     where user_id=auth.uid() for update;
    if not found then return jsonb_build_object('ok',false,'code','WALLET_NOT_FOUND'); end if;
    select * into v_tx from private.worth_it_calc_transactions
     where user_id=auth.uid() and request_id=p_request_id for update;
    if not found then return jsonb_build_object('ok',false,'code','RESERVATION_NOT_FOUND'); end if;
    if v_tx.status='refunded' then return jsonb_build_object('ok',true,'duplicate',true,'status','refunded'); end if;
    if v_tx.status<>'reserved' then return jsonb_build_object('ok',false,'code','RESERVATION_ALREADY_SETTLED'); end if;
    update private.worth_it_calc_transactions set status='refunded' where id=v_tx.id;
    v_refund:=greatest(0,-v_tx.amount_milli);
    if v_refund>0 then
        update private.worth_it_calc_wallets
           set balance_milli=balance_milli+v_refund,updated_at=now()
         where user_id=auth.uid() returning * into v_wallet;
        insert into private.worth_it_calc_transactions(
            user_id,kind,currency,amount_milli,balance_after_milli,status,description,metadata
        ) values(auth.uid(),'refund','CALC',v_refund,v_wallet.balance_milli,'completed',
            'Fixture refund for an unsuccessful operation',
            jsonb_build_object('original_transaction_id',v_tx.id,'original_request_id',p_request_id));
    end if;
    return jsonb_build_object('ok',true,'status','refunded','balance_milli',v_wallet.balance_milli);
end;
$function$;

revoke all on function public.calc_wallet_summary() from public,anon;
revoke all on function public.calc_wallet_refund(uuid) from public,anon;
grant execute on function public.calc_wallet_summary() to authenticated;
grant execute on function public.calc_wallet_refund(uuid) to authenticated;
